#!/usr/bin/env bash
# NexusNet Node - single-file installer / updater (the program is embedded below).
#   bash <(curl -fsSL https://raw.githubusercontent.com/SiNaKeEn/NexusNet-Node/Multi/install.sh)
# Version: 4.5.2
# Usage:   install.sh                 install / update
#          install.sh --extract [DIR] unpack the full source tree (to edit it; rebuild with tools/build_installer.py)
# Env: NXT_PREFIX (default /opt/nexusnet)  NXT_NO_LAUNCH=1 (do not open the menu afterwards)
set -euo pipefail

PREFIX="${NXT_PREFIX:-/opt/nexusnet}"
BIN="${NXT_BIN:-/usr/local/bin}"
R=$'\e[1;31m'; G=$'\e[1;32m'; Y=$'\e[1;33m'; C=$'\e[1;36m'; N=$'\e[0m'

say()  { echo -e "${C}[*]${N} $*"; }
ok()   { echo -e "${G}[+]${N} $*"; }
die()  { echo -e "${R}[-]${N} $*" >&2; exit 1; }

payload() {
  sed -n '/^base64 -d <<.NXT_PAYLOAD.*/,/^NXT_PAYLOAD$/p' "$0" | sed '1d;$d' | base64 -d
}

if [ "${1:-}" = "--extract" ]; then
  DEST="${2:-NexusNet-Node-src}"
  mkdir -p "$DEST"
  payload | tar -xz -C "$DEST" || die "Cannot extract (run this from the saved install.sh file, not via a pipe)"
  ok "Source extracted to $DEST   (edit, then: python3 tools/build_installer.py)"
  exit 0
fi

[ "$(id -u)" -eq 0 ] || die "Run as root:  sudo bash install.sh"
if [ -z "${NXT_SKIP_APT:-}" ]; then
  command -v apt-get >/dev/null 2>&1 || die "Only Debian/Ubuntu (apt) are supported."
  say "Installing system packages..."
  export DEBIAN_FRONTEND=noninteractive
  apt-get update -qq
  apt-get install -y -qq python3 python3-requests python3-socks python3-paramiko curl ca-certificates tar >/dev/null \
    || die "apt install failed"
  python3 -c "import requests, socks" 2>/dev/null || {
    say "apt packages incomplete, falling back to pip..."
    apt-get install -y -qq python3-pip >/dev/null
    pip3 install --quiet --break-system-packages requests "requests[socks]" 2>/dev/null \
      || pip3 install --quiet requests "requests[socks]"
  }
fi
python3 -c 'import sys; sys.exit(0 if sys.version_info >= (3, 8) else 1)' || die "Python 3.8+ required"

TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
say "Unpacking NexusNet Node 4.5.2 ..."
base64 -d <<'NXT_PAYLOAD' | tar -xz -C "$TMP" || die "Corrupted installer (re-download it)"
